-- ================================================================
-- /methodology stops describing a grade it could not show, and prints it.
-- ================================================================
--
-- Migration 613 gave every one of the 340 hosts this site cites a tier,
-- and installed the standing assertion that nothing may be cited from an
-- ungraded host. This migration is the reader-facing half.
--
-- WHAT CHANGES ON THE PAGE. A new section, "Where our citations come
-- from", printing the four tiers with their definitions and the live
-- count against each -- queried, not typed, for the same reason every
-- other figure on that page is queried: this project has had a
-- hand-swept number sit stale across thirty files for two days.
--
-- AND ONE PARAGRAPH IS REPLACED, which is the part worth reading twice.
-- method.gap.p1 said: "We do not publish a grade against each country
-- claim ... whether that source is a statute or a professional tracker
-- is not yet recorded in a form we can show you." That was true when it
-- was written on 22 August and it is false now. Leaving it in place,
-- one section below a table of exactly that grade, would have been the
-- guides defect again -- a page contradicting itself on one screen --
-- on the page whose entire subject is being careful.
--
-- The replacement states the gap that genuinely remains: the grade is
-- per publisher, not per citation, so a blog post on a government domain
-- grades primary and a statute reproduced by a law firm grades
-- secondary. That limitation is real, it is cheap to fix the day a
-- citation needs it, and saying so is the whole point of the section.
--
-- Generated by gen_source_tier_strings.py -- edit that, not this.
-- ================================================================

-- ---- the strings ----------------------------------------------------
INSERT OR REPLACE INTO translations (namespace, key, lang, value)
  VALUES ('tracker', 'method.gap.p1', 'en', 'The grade above belongs to the publisher, not to the individual citation. A page on a government domain is graded primary even if it is a blog post there, and a statute reproduced verbatim by a law firm is graded secondary. No citation we hold has needed an exception yet; when one does, it will get one.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value)
  VALUES ('tracker', 'method.gap.p1', 'de', 'Die obige Bewertung gilt dem Herausgeber, nicht dem einzelnen Beleg. Eine Seite auf einer Behördendomain gilt als primär, selbst wenn sie dort ein Blogbeitrag ist, und ein von einer Kanzlei wortgleich wiedergegebenes Gesetz gilt als sekundär. Bisher brauchte kein Beleg eine Ausnahme; sobald einer sie braucht, bekommt er sie.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value)
  VALUES ('tracker', 'method.gap.p1', 'fr', 'Le classement ci-dessus porte sur l''éditeur, pas sur la citation individuelle. Une page sur un domaine gouvernemental est classée primaire même s''il s''agit d''un billet de blog, et un texte de loi reproduit mot pour mot par un cabinet est classé secondaire. Aucune de nos citations n''a encore eu besoin d''une exception ; le jour où l''une en aura besoin, elle l''aura.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value)
  VALUES ('tracker', 'method.gap.p1', 'es', 'La clasificación anterior corresponde al editor, no a la cita concreta. Una página en un dominio gubernamental se clasifica como primaria aunque allí sea una entrada de blog, y una ley reproducida literalmente por un despacho se clasifica como secundaria. Ninguna de nuestras citas ha necesitado todavía una excepción; cuando alguna la necesite, la tendrá.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value)
  VALUES ('tracker', 'method.tier.count', 'en', '{0} citations across {1} publishers, every one of them graded. Nothing can be published on this site citing a publisher that has not been graded — the build refuses it.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value)
  VALUES ('tracker', 'method.tier.count', 'de', '{0} Belege von {1} Herausgebern, jeder einzelne bewertet. Auf dieser Website kann nichts veröffentlicht werden, das einen unbewerteten Herausgeber zitiert — der Build verweigert es.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value)
  VALUES ('tracker', 'method.tier.count', 'fr', '{0} citations issues de {1} éditeurs, toutes classées. Rien ne peut être publié sur ce site en citant un éditeur non classé : la compilation le refuse.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value)
  VALUES ('tracker', 'method.tier.count', 'es', '{0} citas de {1} editores, todas clasificadas. Nada puede publicarse en este sitio citando a un editor sin clasificar: la compilación lo rechaza.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value)
  VALUES ('tracker', 'method.tier.d.institutional', 'en', 'Official, but not the jurisdiction''s own authority: the European Commission, OpenPeppol and the national Peppol authorities, standards bodies. Authoritative about a specification, not about a national obligation.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value)
  VALUES ('tracker', 'method.tier.d.institutional', 'de', 'Amtlich, aber nicht die Behörde der Jurisdiktion selbst: die Europäische Kommission, OpenPeppol und die nationalen Peppol-Behörden, Normungsgremien. Maßgeblich für eine Spezifikation, nicht für eine nationale Pflicht.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value)
  VALUES ('tracker', 'method.tier.d.institutional', 'fr', 'Officielle, mais pas l''autorité de la juridiction elle-même : la Commission européenne, OpenPeppol et les autorités Peppol nationales, les organismes de normalisation. Fait autorité sur une spécification, pas sur une obligation nationale.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value)
  VALUES ('tracker', 'method.tier.d.institutional', 'es', 'Oficial, pero no la autoridad de la propia jurisdicción: la Comisión Europea, OpenPeppol y las autoridades Peppol nacionales, los organismos de normalización. Autoridad sobre una especificación, no sobre una obligación nacional.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value)
  VALUES ('tracker', 'method.tier.d.primary', 'en', 'The jurisdiction''s own voice — its tax authority, its ministry, its official gazette or state legal register, its own e-invoicing platform.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value)
  VALUES ('tracker', 'method.tier.d.primary', 'de', 'Die Stimme der Jurisdiktion selbst — ihre Steuerbehörde, ihr Ministerium, ihr Amtsblatt oder staatliches Rechtsregister, ihre eigene E-Invoicing-Plattform.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value)
  VALUES ('tracker', 'method.tier.d.primary', 'fr', 'La voix de la juridiction elle-même — son administration fiscale, son ministère, son journal officiel ou registre juridique d''État, sa propre plateforme de facturation électronique.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value)
  VALUES ('tracker', 'method.tier.d.primary', 'es', 'La voz de la propia jurisdicción: su administración tributaria, su ministerio, su boletín oficial o registro jurídico estatal, su propia plataforma de facturación electrónica.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value)
  VALUES ('tracker', 'method.tier.d.secondary', 'en', 'Everyone reporting on the law rather than making it — professional trackers, accountancy and law firms, software vendors, professional bodies, the press, and the private databases that reproduce statute. Useful, often first, never sufficient on its own.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value)
  VALUES ('tracker', 'method.tier.d.secondary', 'de', 'Alle, die über das Recht berichten, statt es zu setzen — Fachtracker, Wirtschaftsprüfer und Kanzleien, Softwareanbieter, Berufsverbände, die Presse und private Datenbanken, die Gesetzestexte wiedergeben. Nützlich, oft zuerst da, allein nie ausreichend.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value)
  VALUES ('tracker', 'method.tier.d.secondary', 'fr', 'Tous ceux qui rendent compte du droit sans le faire — trackers professionnels, cabinets comptables et juridiques, éditeurs de logiciels, ordres professionnels, presse, et bases de données privées qui reproduisent les textes. Utiles, souvent les premiers, jamais suffisants à eux seuls.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value)
  VALUES ('tracker', 'method.tier.d.secondary', 'es', 'Todos los que informan sobre la ley sin hacerla: rastreadores profesionales, firmas contables y jurídicas, proveedores de software, colegios profesionales, la prensa y las bases de datos privadas que reproducen la norma. Útiles, a menudo los primeros, nunca suficientes por sí solos.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value)
  VALUES ('tracker', 'method.tier.d.unknown', 'en', 'We could not establish who operates the host. Recorded as ungraded, with the reason, rather than quietly rounded up to something better.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value)
  VALUES ('tracker', 'method.tier.d.unknown', 'de', 'Wir konnten nicht feststellen, wer den Host betreibt. Als unbewertet mit Begründung erfasst, statt stillschweigend besser eingestuft zu werden.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value)
  VALUES ('tracker', 'method.tier.d.unknown', 'fr', 'Nous n''avons pas pu établir qui exploite l''hôte. Consignée comme non classée, avec le motif, plutôt que discrètement surclassée.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value)
  VALUES ('tracker', 'method.tier.d.unknown', 'es', 'No pudimos establecer quién opera el host. Se registra como sin clasificar, con el motivo, en lugar de mejorarla en silencio.');
