INSERT OR REPLACE INTO translations (namespace, key, lang, value)
  VALUES ('tracker', 'method.tier.lead', 'en', 'Every source we cite is graded on who is answering. The grade belongs to the publisher, not to the page: a summary of a law is a summary of a law, however good it is.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value)
  VALUES ('tracker', 'method.tier.lead', 'de', 'Jede von uns zitierte Quelle wird danach bewertet, wer antwortet. Die Bewertung gilt dem Herausgeber, nicht der einzelnen Seite: Eine Zusammenfassung eines Gesetzes bleibt eine Zusammenfassung, wie gut sie auch sein mag.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value)
